import{describe,it,expect}from"vitest";import fs from"node:fs";import path from"node:path";const LOCALES_DIR=path.resolve(__dirname,"../../i18n/locales"),SOURCE_LANG="en";function readLocale(e){return JSON.parse(fs.readFileSync(path.join(LOCALES_DIR,`${e}.json`),"utf8"))}function flatten(e,t="",n=[]){for(const[s,a]of Object.entries(e)){const e=t?`${t}.${s}`:s;a&&"object"==typeof a&&!Array.isArray(a)?flatten(a,e,n):n.push(e)}return n}const languages=fs.readdirSync(LOCALES_DIR).filter(e=>e.endsWith(".json")).map(e=>e.replace(".json","")),sourceKeys=flatten(readLocale("en"));describe("i18n locale files",()=>{it("ships an English source dictionary",()=>{expect(languages).toContain("en"),expect(sourceKeys.length).toBeGreaterThan(0)}),it("has no duplicate keys in the English source",()=>{expect(new Set(sourceKeys).size).toBe(sourceKeys.length)});for(const e of languages.filter(e=>"en"!==e))it(`"${e}" defines no key that English is missing`,()=>{const t=flatten(readLocale(e)).filter(e=>!sourceKeys.includes(e));expect(t).toEqual([])})}),describe("homepage translation keys",()=>{const e=[...fs.readFileSync("index.html","utf8").matchAll(/data-i18n(?:-placeholder|-aria-label)?="([^"]+)"/g)].map(e=>e[1]);it("annotates the homepage",()=>{expect(e.length).toBeGreaterThan(0)}),it("resolves every data-i18n key against the English dictionary",()=>{const t=e.filter(e=>!sourceKeys.includes(e));expect(t).toEqual([])})});